  ('provincetown', 'movie', 'published', 'Provincetown', 2024, '1h 38m', ARRAY['Drama', 'Comedy'], 'United States', 'English', 'A washed-up cabaret singer returns to the town that made her famous, only to find the drag scene she once ruled has moved on without her. Forced to mentor the very performer who''s replaced her, she has to decide whether to fight for relevance or finally pass the crown — and figure out who she is when the spotlight isn''t on her anymore.', 'The spotlight doesn''t stay on anyone forever.', 4.3, 'Priya Nathan', NULL, ARRAY['Marcus Bell', 'Theo Diaz', 'Ines Okafor'], ARRAY['Drag', 'Mentorship', 'LGBTQ+'], DATE '2024-03-14', 98, 'https://picsum.photos/seed/provincetown/500/750', NULL, 'from-brand-pink to-pride-blue', false, 0, now() - interval '1440 hours', now() - interval '1 hours'),
  ('the-best-man', 'movie', 'published', 'The Best Man', 2025, '1h 40m', ARRAY['Comedy'], 'United States', 'English', '', NULL, NULL, NULL, NULL, '{}'::text[], '{}'::text[], NULL, NULL, 'https://picsum.photos/seed/the-best-man/500/750', NULL, 'from-pride-yellow to-brand-orange', false, 0, now() - interval '1464 hours', now() - interval '2 hours'),
  ('wildflower', 'movie', 'published', 'Wildflower', 2023, '2h 01m', ARRAY['Drama', 'Romance'], 'United States', 'English', 'Two women meet on a cross-country road trip neither of them planned — one running from a marriage she can''t go back to, the other running toward a life she''s never let herself want. Told over the course of ten days and a thousand miles, Wildflower is a slow-burn romance about the difference between running away and finally moving forward, and what it costs to choose yourself in your forties instead of your twenties.', NULL, 4.6, 'Alex Rivera', NULL, ARRAY['Nadia Torres', 'Claire Whitfield'], ARRAY['Road Trip', 'Slow Burn', 'LGBTQ+'], DATE '2023-09-08', 121, 'https://picsum.photos/seed/wildflower/500/750', NULL, 'from-pride-green to-pride-purple', false, 0, now() - interval '1488 hours', now() - interval '3 hours'),
